-- Generated synthetic data. Apply AFTER 001_initial.sql to an EMPTY dispatch schema.
-- No plans/events are simulated by this import. Re-running is intentionally rejected.
BEGIN;
SET LOCAL search_path = dispatch, public;
SET LOCAL standard_conforming_strings = on;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM service_centers) OR EXISTS (SELECT 1 FROM planning_days) OR EXISTS (SELECT 1 FROM training_orders) THEN RAISE EXCEPTION 'Import requires empty tables; no data was overwritten'; END IF; END $$;
COMMIT;
SELECT 'service_centers' AS entity, count(*) FROM dispatch.service_centers UNION ALL SELECT 'staff',count(*) FROM dispatch.staff UNION ALL SELECT 'orders',count(*) FROM dispatch.orders UNION ALL SELECT 'training_orders',count(*) FROM dispatch.training_orders;
